select date_trunc('quarter', txn_time) as quarter_start, case when amount >= 4100 then 'LARGE' else 'SMALL' end as amount_tier, stddev_samp(amount) as amount_stddev, count(distinct merchant) as distinct_merchants, sum(case when txn_type = 'FEE' then amount else 0 end) as fee_amount, size(collect_set(merchant)) as num_merchants, min(txn_time) as started_at, min(txn_time) as first_txn_time, rank() over (partition by date_trunc('quarter', txn_time) order by stddev_samp(amount) desc) as amount_stddev_rank from transactions group by quarter_start, amount_tier order by fee_amount nulls first;
